/// <reference path="tedit-api.d.ts" />
// Find Life Crystals - Locates all Life Crystal sprites and shows them in the Find sidebar
// Life Crystal tile type is 12 (2x2 sprite), anchorOnly=true returns one result per crystal

finder.clear();
var results = batch.findTilesByType(12, true);

log.print("Found " + results.length + " Life Crystals");
for (var i = 0; i < results.length; i++) {
    finder.addResult("Life Crystal", results[i].x, results[i].y, "Script");
}

if (results.length > 0) {
    finder.navigateFirst();
}

geometric-mandala.js:
/// <reference path="tedit-api.d.ts" />
// Geometric Mandala - Creates a symmetric geometric pattern using stone blocks
// Place your selection where you want the pattern centered, or it uses world spawn
// The pattern has 8-fold symmetry with concentric rings, rays, and diamond accents

var STONE = 1;
var GOLD = 167;    // Gold Brick
var DIAMOND = 117; // Amethyst (purple gem)
var OBSIDIAN = 56;

// Determine center point from selection or spawn
var cx, cy;
if (selection.isActive) {
    cx = Math.floor(selection.x + selection.width / 2);
    cy = Math.floor(selection.y + selection.height / 2);
} else {
    cx = world.spawnX;
    cy = world.spawnY;
}

var radius = 40;
var placed = 0;

// Helper: place a tile at (x,y) with bounds checking
function place(x, y, tileType) {
    if (x >= 0 && x < world.width && y >= 0 && y < world.height) {
        tile.setActive(x, y, true);
        tile.setType(x, y, tileType);
        placed++;
    }
}

// Helper: mirror a point with 8-fold symmetry around center
function mirror8(dx, dy, tileType) {
    place(cx + dx, cy + dy, tileType);
    place(cx - dx, cy + dy, tileType);
    place(cx + dx, cy - dy, tileType);
    place(cx - dx, cy - dy, tileType);
    place(cx + dy, cy + dx, tileType);
    place(cx - dy, cy + dx, tileType);
    place(cx + dy, cy - dx, tileType);
    place(cx - dy, cy - dx, tileType);
}

log.print("Drawing mandala centered at (" + cx + ", " + cy + ") with radius " + radius);

// --- Concentric rings ---
var ringRadii = [10, 20, 30, 40];
for (var r = 0; r < ringRadii.length; r++) {
    var rad = ringRadii[r];
    var ringType = (r % 2 === 0) ? STONE : GOLD;
    var points = geometry.ellipse(cx, cy, rad, rad);
    for (var i = 0; i < points.length; i++) {
        place(points[i].x, points[i].y, ringType);
    }
    log.progress((r + 1) / (ringRadii.length + 8));
}

// --- 8 radial rays from center ---
var angles = 8;
for (var a = 0; a < angles; a++) {
    var angle = (a * Math.PI * 2) / angles;
    var x2 = cx + Math.round(Math.cos(angle) * radius);
    var y2 = cy + Math.round(Math.sin(angle) * radius);
    var rayPoints = geometry.line(cx, cy, x2, y2);
    for (var i = 0; i < rayPoints.length; i++) {
        place(rayPoints[i].x, rayPoints[i].y, STONE);
    }
    log.progress((ringRadii.length + a + 1) / (ringRadii.length + angles));
}

// --- Diamond accents between rings ---
var diamondOffsets = [15, 25, 35];
for (var d = 0; d < diamondOffsets.length; d++) {
    var dist = diamondOffsets[d];
    var size = 3;
    // Place diamonds along 8 axes
    for (var a = 0; a < 8; a++) {
        var angle = (a * Math.PI * 2) / 8;
        var dcx = cx + Math.round(Math.cos(angle) * dist);
        var dcy = cy + Math.round(Math.sin(angle) * dist);
        // Draw small diamond shape
        for (var s = 0; s <= size; s++) {
            place(dcx + s, dcy, DIAMOND);
            place(dcx - s, dcy, DIAMOND);
            place(dcx, dcy + s, DIAMOND);
            place(dcx, dcy - s, DIAMOND);
        }
    }
}

// --- Inner starburst pattern ---
for (var a = 0; a < 16; a++) {
    var angle = (a * Math.PI * 2) / 16;
    var innerLen = (a % 2 === 0) ? 8 : 5;
    var x2 = cx + Math.round(Math.cos(angle) * innerLen);
    var y2 = cy + Math.round(Math.sin(angle) * innerLen);
    var starPoints = geometry.line(cx, cy, x2, y2);
    var starType = (a % 2 === 0) ? OBSIDIAN : GOLD;
    for (var i = 0; i < starPoints.length; i++) {
        place(starPoints[i].x, starPoints[i].y, starType);
    }
}

// --- Decorative arcs between the outer rays ---
for (var a = 0; a < 8; a++) {
    var angle1 = (a * Math.PI * 2) / 8;
    var angle2 = ((a + 1) * Math.PI * 2) / 8;
    var midAngle = (angle1 + angle2) / 2;
    // Scallop arc: 5 points along arc between rays at radius 38
    for (var t = 0; t <= 6; t++) {
        var frac = t / 6;
        var arcAngle = angle1 + frac * (angle2 - angle1);
        // Vary radius to create scalloped edge
        var arcR = 38 + Math.round(3 * Math.sin(frac * Math.PI));
        var ax = cx + Math.round(Math.cos(arcAngle) * arcR);
        var ay = cy + Math.round(Math.sin(arcAngle) * arcR);
        place(ax, ay, OBSIDIAN);
    }
}

log.progress(1.0);
log.print("Mandala complete! Placed " + placed + " tiles.");
log.print("Materials: Stone, Gold Brick, Amethyst, Obsidian");

replace-block.js:
/// <reference path="tedit-api.d.ts" />
// Replace Block - Replace one tile type with another in the current selection
// Edit the fromType and toType values below to customize

var fromType = 1;  // Stone
var toType = 56;   // Obsidian

if (!selection.isActive) {
    log.warn("No selection active - operating on entire world");
}

var count = 0;

if (selection.isActive) {
    count = batch.replaceTileInSelection(fromType, toType);
} else {
    count = batch.replaceTile(fromType, toType);
}

var fromName = metadata.tileName(fromType) || ("Tile #" + fromType);
var toName = metadata.tileName(toType) || ("Tile #" + toType);
log.print("Replaced " + count + " " + fromName + " tiles with " + toName);

save-all-difficulties.js:
/// <reference path="tedit-api.d.ts" />
// Save All Difficulties - Save the current world as all 4 difficulties
// Parses the world title and file name to swap the difficulty word.
//
// Expected format:
//   World Name: "Shimmering Skies - Journey 1.7"
//   File Name:  "ShimmeringSkies-Journey-1.7.wld"
//
// Produces 4 files in the same folder as the source file:
//   ShimmeringSkies-Classic-1.7.wld  (GameMode 0)
//   ShimmeringSkies-Expert-1.7.wld   (GameMode 1)
//   ShimmeringSkies-Master-1.7.wld   (GameMode 2)
//   ShimmeringSkies-Journey-1.7.wld  (GameMode 3)
//
// If no path separators in the file name, saves to the default worlds folder.

var difficulties = [
    { mode: 0, name: "Classic" },
    { mode: 1, name: "Expert" },
    { mode: 2, name: "Master" },
    { mode: 3, name: "Journey" }
];

var originalTitle = world.title;
var originalMode = world.gameMode;
var originalPath = tools.getFilePath();

if (!originalPath) {
    log.error("No file path set. Save the world first.");
} else {
    // Extract directory and file name parts
    var lastSlash = originalPath.lastIndexOf("\\");
    if (lastSlash < 0) lastSlash = originalPath.lastIndexOf("/");
    var dir = lastSlash >= 0 ? originalPath.substring(0, lastSlash + 1) : "";
    var fileName = lastSlash >= 0 ? originalPath.substring(lastSlash + 1) : originalPath;
    var baseName = fileName.replace(/\.wld$/i, "");

    // Find which difficulty word is in the current title and file name
    var currentDiffName = "";
    for (var i = 0; i < difficulties.length; i++) {
        if (originalTitle.indexOf(difficulties[i].name) >= 0) {
            currentDiffName = difficulties[i].name;
            break;
        }
    }

    if (!currentDiffName) {
        log.warn("Could not detect difficulty in world title: " + originalTitle);
        log.warn("Will append difficulty to title and file name instead.");
    }

    log.print("World title:  " + originalTitle);
    log.print("File:         " + fileName);
    log.print("Worlds folder: " + tools.getWorldsFolder());
    log.print("Detected difficulty: " + (currentDiffName || "(none)"));
    log.print("---");

    var saved = 0;
    for (var d = 0; d < difficulties.length; d++) {
        var diff = difficulties[d];
        log.progress((d + 0.1) / difficulties.length);

        // Build new title
        var newTitle;
        if (currentDiffName) {
            newTitle = originalTitle.replace(currentDiffName, diff.name);
        } else {
            newTitle = originalTitle + " - " + diff.name;
        }

        // Build new file name
        var newBaseName;
        if (currentDiffName) {
            newBaseName = baseName.replace(currentDiffName, diff.name);
        } else {
            newBaseName = baseName + "-" + diff.name;
        }
        var newPath = dir + newBaseName + ".wld";

        // Apply changes
        world.title = newTitle;
        world.gameMode = diff.mode;

        log.print("Saving " + diff.name + ": " + newTitle);
        log.print("  -> " + newPath);

        var ok = tools.saveAs(newPath);
        if (ok) {
            saved++;
        } else {
            log.error("Failed to save: " + newPath);
        }

        log.progress((d + 1) / difficulties.length);
    }

    // Restore original state
    world.title = originalTitle;
    world.gameMode = originalMode;
    tools.setFilePath(originalPath);

    log.print("---");
    log.print("Done! Saved " + saved + "/" + difficulties.length + " files.");
}

tedit-api.d.ts:
// TEdit Scripting API - TypeScript Declarations
// Generated from ScriptApiMetadata and C# source classes.
// Place alongside your .js scripts for editor autocomplete.
//
// Global objects available in TEdit scripts:
//   tile, batch, geometry, selection, chests, signs, npcs,
//   world, metadata, log, tools, finder, sprites, draw,
//   tileEntities, generate, print

// ─── Common Shapes ──────────────────────────────────────────────────────────

interface Point {
    x: number;
    y: number;
}

interface ChestItem {
    slot: number;
    id: number;
    name: string;
    stack: number;
    prefix: number;
}

interface ChestInfo {
    x: number;
    y: number;
    name: string;
    items: ChestItem[];
}

interface SignInfo {
    x: number;
    y: number;
    text: string;
}

interface NpcInfo {
    name: string;
    displayName: string;
    spriteId: number;
    x: number;
    y: number;
    homeX: number;
    homeY: number;
    isHomeless: boolean;
}

interface IdName {
    id: number;
    name: string;
}

/** Biome shape types for controlling biome region geometry. */
type BiomeShape = "rectangle" | "ellipse" | "diagonalLeft" | "diagonalRight" | "trapezoid" | "hemisphere";

interface TreeTypeInfo {
    name: string;
    tileId: number;
}

interface OreTypeInfo {
    name: string;
    tileId: number;
}

interface SpriteSheetInfo {
    tileId: number;
    name: string;
    styleCount: number;
}

interface SpriteStyleInfo {
    index: number;
    name: string;
    width: number;
    height: number;
}

interface TileEntityInfo {
    x: number;
    y: number;
    type: string;
    id: number;
    [key: string]: any;
}

// ─── tile ────────────────────────────────────────────────────────────────────

/** Low-level tile read/write operations. */
declare const tile: {
    /** Check if tile at (x, y) is active (has a block). */
    isActive(x: number, y: number): boolean;
    /** Get tile type ID at (x, y). */
    getTileType(x: number, y: number): number;
    /** Get wall type ID at (x, y). */
    getWall(x: number, y: number): number;
    /** Get tile paint color at (x, y). */
    getPaint(x: number, y: number): number;
    /** Get wall paint color at (x, y). */
    getWallPaint(x: number, y: number): number;
    /** Get liquid amount (0-255) at (x, y). */
    getLiquidAmount(x: number, y: number): number;
    /** Get liquid type (0=none, 1=water, 2=lava, 3=honey) at (x, y). */
    getLiquidType(x: number, y: number): number;
    /** Get sprite frame U coordinate at (x, y). */
    getFrameU(x: number, y: number): number;
    /** Get sprite frame V coordinate at (x, y). */
    getFrameV(x: number, y: number): number;
    /** Get slope type as string at (x, y). */
    getSlope(x: number, y: number): string;
    /** Check wire state. color: 1=red, 2=blue, 3=green, 4=yellow. */
    getWire(x: number, y: number, color: number): boolean;
    /** Check if tile has echo (invisible) coating at (x, y). */
    getTileEcho(x: number, y: number): boolean;
    /** Check if wall has echo (invisible) coating at (x, y). */
    getWallEcho(x: number, y: number): boolean;
    /** Check if tile has illuminant (full bright) coating at (x, y). */
    getTileIlluminant(x: number, y: number): boolean;
    /** Check if wall has illuminant (full bright) coating at (x, y). */
    getWallIlluminant(x: number, y: number): boolean;

    /** Set tile active state at (x, y). */
    setActive(x: number, y: number, active: boolean): void;
    /** Set tile type at (x, y). Also activates the tile. */
    setType(x: number, y: number, type: number): void;
    /** Set wall type at (x, y). */
    setWall(x: number, y: number, wallType: number): void;
    /** Set tile paint color at (x, y). */
    setPaint(x: number, y: number, color: number): void;
    /** Set wall paint color at (x, y). */
    setWallPaint(x: number, y: number, color: number): void;
    /** Set liquid amount and type at (x, y). */
    setLiquid(x: number, y: number, amount: number, type: number): void;
    /** Set wire state. color: 1=red, 2=blue, 3=green, 4=yellow. */
    setWire(x: number, y: number, color: number, enabled: boolean): void;
    /** Set slope type. Values: "None", "HalfBrick", "SlopeTopRight", "SlopeTopLeft", "SlopeBottomRight", "SlopeBottomLeft". */
    setSlope(x: number, y: number, slope: string): void;
    /** Set sprite frame coordinates at (x, y). */
    setFrameUV(x: number, y: number, u: number, v: number): void;
    /** Set tile echo (invisible) coating at (x, y). */
    setTileEcho(x: number, y: number, value: boolean): void;
    /** Set wall echo (invisible) coating at (x, y). */
    setWallEcho(x: number, y: number, value: boolean): void;
    /** Set tile illuminant (full bright) coating at (x, y). */
    setTileIlluminant(x: number, y: number, value: boolean): void;
    /** Set wall illuminant (full bright) coating at (x, y). */
    setWallIlluminant(x: number, y: number, value: boolean): void;
    /** Reset tile to default empty state. */
    clear(x: number, y: number): void;
    /** Copy all properties from one tile to another. */
    copy(fromX: number, fromY: number, toX: number, toY: number): void;
};

// ─── batch ───────────────────────────────────────────────────────────────────

/** High-performance bulk operations across world or selection. */
declare const batch: {
    /** Iterate entire world, calls callback(x, y) for each tile. */
    forEachTile(callback: (x: number, y: number) => void): void;
    /** Iterate selection area, calls callback(x, y). */
    forEachInSelection(callback: (x: number, y: number) => void): void;
    /** Find tiles matching predicate (max 10,000 results). */
    findTiles(predicate: (x: number, y: number) => boolean): Point[];
    /** Find tiles of a specific type. anchorOnly=true returns only sprite origin tiles. */
    findTilesByType(tileType: number, anchorOnly?: boolean): Point[];
    /** Find all tiles with specific wall type (max 10,000). */
    findTilesByWall(wallType: number): Point[];
    /** Replace all tiles of one type with another. Returns count replaced. */
    replaceTile(fromType: number, toType: number): number;
    /** Replace tiles in selection only. Returns count replaced. */
    replaceTileInSelection(fromType: number, toType: number): number;
    /** Replace all walls of one type with another. Returns count replaced. */
    replaceWall(fromType: number, toType: number): number;
    /** Clear all tiles of specified type. Returns count cleared. */
    clearTilesByType(tileType: number): number;
};

// ─── geometry ────────────────────────────────────────────────────────────────

/** Shape generation and bulk fill operations. */
declare const geometry: {
    /** Generate line coordinates between two points. */
    line(x1: number, y1: number, x2: number, y2: number): Point[];
    /** Generate rectangle outline coordinates. */
    rect(x: number, y: number, w: number, h: number): Point[];
    /** Generate ellipse outline coordinates. */
    ellipse(cx: number, cy: number, rx: number, ry: number): Point[];
    /** Generate filled rectangle coordinates. */
    fillRect(x: number, y: number, w: number, h: number): Point[];
    /** Generate filled ellipse coordinates. */
    fillEllipse(cx: number, cy: number, rx: number, ry: number): Point[];
    /** Fill rectangle with tile type. */
    setTiles(tileType: number, x: number, y: number, w: number, h: number): void;
    /** Fill rectangle with wall type. */
    setWalls(wallType: number, x: number, y: number, w: number, h: number): void;
    /** Clear all tiles in rectangle. */
    clearTiles(x: number, y: number, w: number, h: number): void;
};

// ─── selection ───────────────────────────────────────────────────────────────

/** Query and manipulate the current selection rectangle. */
declare const selection: {
    /** Whether a selection is active. */
    readonly isActive: boolean;
    /** Selection X coordinate. */
    readonly x: number;
    /** Selection Y coordinate. */
    readonly y: number;
    /** Selection width. */
    readonly width: number;
    /** Selection height. */
    readonly height: number;
    /** Left edge. */
    readonly left: number;
    /** Top edge. */
    readonly top: number;
    /** Right edge (exclusive). */
    readonly right: number;
    /** Bottom edge (exclusive). */
    readonly bottom: number;
    /** Create and activate a selection. */
    set(x: number, y: number, width: number, height: number): void;
    /** Deactivate selection. */
    clear(): void;
    /** Check if coordinate is in selection. */
    contains(x: number, y: number): boolean;
};

// ─── chests ──────────────────────────────────────────────────────────────────

/** Query and modify chest inventories. */
declare const chests: {
    /** Total number of chests. */
    readonly count: number;
    /** Get all chests. */
    getAll(): ChestInfo[];
    /** Get chest at tile coordinates. */
    getAt(x: number, y: number): ChestInfo | null;
    /** Find chests containing item ID. */
    findByItem(itemId: number): ChestInfo[];
    /** Find chests containing item by name. */
    findByItemName(name: string): ChestInfo[];
    /** Find chests by name (partial match). */
    findByName(name: string): ChestInfo[];
    /** Set item in specific slot. */
    setItem(x: number, y: number, slot: number, itemId: number, stack: number, prefix: number): void;
    /** Clear item from slot. */
    clearItem(x: number, y: number, slot: number): void;
    /** Set chest name/label. */
    setName(x: number, y: number, name: string): void;
    /** Add item to first empty slot. Returns true if added. */
    addItem(x: number, y: number, itemId: number, stack: number, prefix: number): boolean;
};

// ─── signs ───────────────────────────────────────────────────────────────────

/** Read and modify sign text. */
declare const signs: {
    /** Total number of signs. */
    readonly count: number;
    /** Get all signs. */
    getAll(): SignInfo[];
    /** Get sign at tile coordinates. */
    getAt(x: number, y: number): SignInfo | null;
    /** Update sign text. */
    setText(x: number, y: number, text: string): void;
};

// ─── npcs ────────────────────────────────────────────────────────────────────

/** Query and modify world NPCs (town NPCs, bosses, enemies, and all bestiary entries). */
declare const npcs: {
    /** Total number of NPCs. */
    readonly count: number;
    /** Get all NPCs including duplicates of the same type. */
    getAll(): NpcInfo[];
    /** Set home for first NPC matching name (by Name or DisplayName, case-insensitive). */
    setHome(name: string, x: number, y: number): void;
    /** Set home for Nth NPC matching name (0-based index for duplicates). */
    setHome(name: string, x: number, y: number, index: number): void;
    /** Set home for all NPCs matching name. Returns count of NPCs moved. */
    setHomeAll(name: string, x: number, y: number): number;
    /** Create NPC by name, fullName, bestiaryId, or numeric sprite ID. Supports all bestiary entries. */
    create(name: string, displayName: string, x: number, y: number): void;
    /** Remove first NPC matching name. Returns true if removed. */
    remove(name: string): boolean;
};

// ─── world ───────────────────────────────────────────────────────────────────

/** Read and modify world properties. Properties marked readonly cannot be set. */
declare const world: {
    // World Size
    readonly width: number;
    readonly height: number;

    // Metadata
    title: string;
    worldId: number;
    seed: string;
    isFavorite: boolean;
    isChinese: boolean;
    isConsole: boolean;
    fileRevision: number;
    worldGenVersion: number;
    creationTime: number;
    lastPlayed: number;

    // Spawn & Dungeon
    spawnX: number;
    spawnY: number;
    dungeonX: number;
    dungeonY: number;

    // Levels
    surfaceLevel: number;
    rockLevel: number;
    safeGroundLayers: boolean;

    // Time
    time: number;
    dayTime: boolean;
    fastForwardTime: boolean;
    sundialCooldown: number;
    fastForwardTimeToDusk: boolean;
    moondialCooldown: number;

    // Moon
    moonPhase: number;
    bloodMoon: boolean;
    moonType: number;
    isEclipse: boolean;

    // Weather
    isRaining: boolean;
    tempRainTime: number;
    tempMaxRain: number;
    slimeRainTime: number;
    tempMeteorShowerCount: number;
    tempCoinRain: number;
    numClouds: number;
    windSpeedSet: number;
    cloudBgActive: number;

    // Sandstorm
    sandStormHappening: boolean;
    sandStormTimeLeft: number;
    sandStormSeverity: number;
    sandStormIntendedSeverity: number;

    // Holidays
    forceHalloweenForToday: boolean;
    forceXMasForToday: boolean;
    forceHalloweenForever: boolean;
    forceXMasForever: boolean;

    // Difficulty
    hardMode: boolean;
    gameMode: number;
    spawnMeteor: boolean;
    combatBookUsed: boolean;
    combatBookVolumeTwoWasUsed: boolean;
    peddlersSatchelWasUsed: boolean;
    partyOfDoom: boolean;

    // World Seeds
    drunkWorld: boolean;
    goodWorld: boolean;
    tenthAnniversaryWorld: boolean;
    dontStarveWorld: boolean;
    notTheBeesWorld: boolean;
    remixWorld: boolean;
    noTrapsWorld: boolean;
    zenithWorld: boolean;
    skyblockWorld: boolean;
    vampireSeed: boolean;
    infectedSeed: boolean;
